INSERT INTO cms.website_content (id, draft, published, previous, revision, published_at, updated_at) VALUES ('main', '{"company":{"nameEn":"Al-Mizan Advocates & Legal Consultants","nameAr":"مكتب الميزان للمحاماة والاستشارات القانونية","shortEn":"Al-Mizan Law","shortAr":"الميزان للمحاماة","taglineEn":"Corporate Law, Arbitration & Commercial Litigation","taglineAr":"قانون الشركات والتحكيم التجاري والتقاضي","aboutEn":"Full-service Bahraini law firm representing financial institutions, family offices, and international investors in commercial arbitration.","aboutAr":"مكتب محاماة بحريني متكامل يمثل المؤسسات المالية والشركات في التحكيم التجاري والعقود."},"hero":{"titleEn":"Al-Mizan Law — Corporate Law, Arbitration & Commercial Litigation","titleAr":"الميزان للمحاماة — قانون الشركات والتحكيم التجاري والتقاضي","ctaLabelEn":"Explore Al-Mizan Law","ctaLabelAr":"استكشف الميزان للمحاماة"},"featuredServices":[{"code":"SVC-RET","en":"Corporate Legal Retainer","ar":"اتفاقية استشارات قانونية شهرية","rate":1200},{"code":"SVC-ARB","en":"Commercial Arbitration Representation","ar":"التمثيل في التحكيم التجاري","rate":4500},{"code":"LAW-CORP","en":"M&A, Shareholder Agreements & Joint Ventures","ar":"اتفاقيات المساهمين والاندماج والاستحواذ","rate":2600},{"code":"LAW-ARB","en":"BCDR & ICC Commercial Arbitration","ar":"التحكيم التجاري لدى غرفة البحرين وICC","rate":4200}]}'::jsonb, '{"company":{"nameEn":"Al-Mizan Advocates & Legal Consultants","nameAr":"مكتب الميزان للمحاماة والاستشارات القانونية","shortEn":"Al-Mizan Law","shortAr":"الميزان للمحاماة","taglineEn":"Corporate Law, Arbitration & Commercial Litigation","taglineAr":"قانون الشركات والتحكيم التجاري والتقاضي","aboutEn":"Full-service Bahraini law firm representing financial institutions, family offices, and international investors in commercial arbitration.","aboutAr":"مكتب محاماة بحريني متكامل يمثل المؤسسات المالية والشركات في التحكيم التجاري والعقود."},"hero":{"titleEn":"Al-Mizan Law — Corporate Law, Arbitration & Commercial Litiga